# Homebrew formula for leradeveloper (macOS, Linux, WSL).
# Generated by the Release workflow in paulopng/leradeveloper — edit the
# template in packaging/ there, not the copy in the tap.
class Leradeveloper < Formula
  desc "Browse, install and track AI agent personas for AI coding tools, in your browser"
  homepage "https://github.com/paulopng/leradeveloper"
  url "https://github.com/paulopng/leradeveloper/releases/download/v@VERSION@/leradeveloper-@VERSION@.tar.gz"
  sha256 "@SHA256_TGZ@"
  license "MIT"

  depends_on "node"

  def install
    libexec.install Dir["*"]
    (bin/"leradeveloper").write <<~SH
      #!/bin/bash
      exec "#{Formula["node"].opt_bin}/node" "#{libexec}/bin/leradeveloper.js" "$@"
    SH
  end

  service do
    run [opt_bin/"leradeveloper", "--no-open"]
    keep_alive true
    log_path var/"log/leradeveloper.log"
    error_log_path var/"log/leradeveloper.log"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/leradeveloper --version")
  end
end
